                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (name.includes('u-tip')) return 'Extensiones U-Tip';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (name.includes('wig')) return 'Pelucas';
